// Level 1 — Base
public class OrderException extends RuntimeException {
    private final String orderId;
    public OrderException(String msg, String orderId) { super(msg); this.orderId=orderId; }
    public OrderException(String msg, String orderId, Throwable cause) { super(msg,cause); this.orderId=orderId; }
    public String getOrderId() { return orderId; }
}

// Level 2 — Category
public class OrderFulfillmentException extends OrderException {
    public OrderFulfillmentException(String msg, String orderId) { super(msg,orderId); }
    public OrderFulfillmentException(String msg, String orderId, Throwable cause) { super(msg,orderId,cause); }
}

// Level 3 — Specific
public class OutOfStockException extends OrderFulfillmentException {
    private final String productId;
    private final int requestedQty;
    private final int availableQty;
    public OutOfStockException(String orderId, String productId, int req, int avail) {
        super("Product " + productId + " out of stock: requested=" + req + ", available=" + avail, orderId);
        this.productId=productId; this.requestedQty=req; this.availableQty=avail;
    }
    public int getShortfall() { return requestedQty - availableQty; }
}

// Usage:
try { fulfilmentService.fulfil(order); }
catch (OutOfStockException e) { notifyBuyer("Sorry, " + e.getShortfall() + " items unavailable"); }
catch (OrderFulfillmentException e) { retryFulfilment(e.getOrderId()); }
catch (OrderException e) { logAndAlert(e); }

